<template>
  <div>
    <div class="page-heading"><div><p class="eyebrow">订单履约</p><h1>收货、质检与退货</h1><p>采购订单到货登记、质量检验和不合格品退货形成同一条可追溯链路。</p></div><el-button type="primary" @click="openCreate">{{createButton}}</el-button></div>
    <el-button @click="deliveriesVisible=true">供应商交付记录</el-button><el-dialog title="供应商交付与物流跟踪" :visible.sync="deliveriesVisible" width="90%" custom-class="analysis-dialog"><SupplierDeliveries v-if="deliveriesVisible" @refresh="load();loadOptions()"/></el-dialog>
    <div class="process-strip"><span>1. 到货登记</span><i>→</i><span>2. 确认收货</span><i>→</i><span>3. 质量检验</span><i>→</i><span>4. 不合格品退货</span></div>
    <el-tabs v-model="active" type="card" @tab-click="changeTab"><el-tab-pane label="收货单" name="receipts"/><el-tab-pane label="质量检验" name="inspections"/><el-tab-pane label="采购退货" name="returns"/></el-tabs>
    <el-table :key="active" v-loading="loading" :data="items" class="data-table" :empty-text="`暂无${activeLabel}`">
      <template v-if="active==='receipts'"><el-table-column prop="receipt_no" label="收货单号" width="140"/><el-table-column prop="order_no" label="采购订单" width="140"/><el-table-column prop="supplier_name" label="供应商" min-width="150"/><el-table-column prop="material_name" label="物料" min-width="150"/><el-table-column prop="received_quantity" label="收货数量" width="100"/><el-table-column prop="received_date" label="收货日期" width="110"/><el-table-column label="质检结果" width="140"><template slot-scope="scope">合格 {{scope.row.accepted_quantity}} / 不合格 {{scope.row.rejected_quantity}}</template></el-table-column><el-table-column label="状态" width="100"><template slot-scope="scope"><el-tag :type="statusType(scope.row.status)">{{statusName(scope.row.status)}}</el-tag></template></el-table-column></template>
      <template v-else-if="active==='inspections'"><el-table-column prop="inspection_no" label="检验单号" width="140"/><el-table-column prop="receipt_no" label="收货单号" width="140"/><el-table-column prop="inspected_quantity" label="检验数量"/><el-table-column prop="accepted_quantity" label="合格数量"/><el-table-column prop="rejected_quantity" label="不合格数量"/><el-table-column prop="rework_quantity" label="返修数量"/><el-table-column label="结论" width="100"><template slot-scope="scope"><el-tag :type="scope.row.result==='passed'?'success':scope.row.result==='failed'?'danger':'warning'">{{statusName(scope.row.result)}}</el-tag></template></el-table-column><el-table-column prop="inspected_by" label="检验人"/></template>
      <template v-else><el-table-column prop="return_no" label="退货单号" width="140"/><el-table-column prop="receipt_no" label="收货单号" width="140"/><el-table-column prop="supplier_name" label="供应商" min-width="160"/><el-table-column prop="material_code" label="物料编码"/><el-table-column prop="quantity" label="退货数量" width="100"/><el-table-column prop="reason" label="退货原因" min-width="180"/><el-table-column label="状态" width="100"><template slot-scope="scope"><el-tag :type="statusType(scope.row.status)">{{statusName(scope.row.status)}}</el-tag></template></el-table-column></template>
      <el-table-column v-if="active!=='inspections'" label="操作" width="170" fixed="right"><template slot-scope="scope"><el-button v-if="active==='receipts'&&scope.row.status==='draft'" type="text" @click="editReceipt(scope.row)">编辑</el-button><el-button v-if="active==='receipts'&&scope.row.status==='draft'" type="text" @click="confirmReceipt(scope.row)">确认收货</el-button><el-button v-if="active==='returns'&&scope.row.status==='draft'" type="text" @click="advanceReturn(scope.row,'sent')">发送</el-button><el-button v-if="active==='returns'&&scope.row.status==='sent'" type="text" @click="advanceReturn(scope.row,'completed')">完成</el-button><el-button v-if="scope.row.status==='draft'" type="text" class="danger-link" @click="remove(scope.row)">删除</el-button></template></el-table-column>
    </el-table>
    <div class="pagination-row"><span>共 {{pagination.total}} 条</span><el-pagination background layout="sizes, prev, pager, next" :page-sizes="[10,20,50]" :current-page="pagination.page" :page-size="pagination.page_size" :total="pagination.total" @current-change="changePage" @size-change="changeSize"/></div>

    <el-dialog :title="dialogTitle" :visible.sync="dialogVisible" width="650px" :close-on-click-modal="false">
      <el-form ref="form" :model="form" label-width="110px">
        <template v-if="active==='receipts'"><el-form-item label="采购订单"><el-select v-model="form.order_id" filterable :disabled="!!editingId" style="width:100%" @change="selectOrder"><el-option v-for="order in orders" :key="order.id" :label="`${order.order_no} · ${order.supplier_name}`" :value="order.id"/></el-select></el-form-item><el-form-item label="到货物料"><el-select v-model="form.material_code" :disabled="!!editingId" style="width:100%" @change="selectOrderMaterial"><el-option v-for="line in selectedOrderLines" :key="line.material_code" :label="`${line.material_code} · ${line.material_name}`" :value="line.material_code"/></el-select></el-form-item><el-row :gutter="16"><el-col :span="12"><el-form-item label="收货数量"><el-input-number v-model="form.received_quantity" :min="0.01" :precision="2" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="收货日期"><el-date-picker v-model="form.received_date" value-format="yyyy-MM-dd" type="date" style="width:100%"/></el-form-item></el-col></el-row><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" :rows="3"/></el-form-item></template>
        <template v-else-if="active==='inspections'"><el-form-item label="待检收货单"><el-select v-model="form.receipt_id" filterable style="width:100%" @change="selectReceipt"><el-option v-for="item in inspectableReceipts" :key="item.id" :label="`${item.receipt_no} · ${item.material_name} · ${item.received_quantity}`" :value="item.id"/></el-select></el-form-item><el-row :gutter="16"><el-col :span="12"><el-form-item label="检验数量"><el-input-number v-model="form.inspected_quantity" :min="0.01" :precision="2" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="合格数量"><el-input-number v-model="form.accepted_quantity" :min="0" :precision="2" style="width:100%"/></el-form-item></el-col></el-row><el-row :gutter="16"><el-col :span="12"><el-form-item label="不合格数量"><el-input-number v-model="form.rejected_quantity" :min="0" :precision="2" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="返修数量"><el-input-number v-model="form.rework_quantity" :min="0" :precision="2" style="width:100%"/></el-form-item></el-col></el-row><el-form-item label="缺陷描述"><el-input v-model="form.defect_description" type="textarea" :rows="3"/></el-form-item></template>
        <template v-else><el-form-item label="不合格收货单"><el-select v-model="form.receipt_id" filterable style="width:100%" @change="selectRejectedReceipt"><el-option v-for="item in returnableReceipts" :key="item.id" :label="`${item.receipt_no} · ${item.material_name} · 不合格${item.rejected_quantity}`" :value="item.id"/></el-select></el-form-item><el-form-item label="退货数量"><el-input-number v-model="form.quantity" :min="0.01" :precision="2" style="width:100%"/></el-form-item><el-form-item label="退货原因"><el-input v-model="form.reason" type="textarea" :rows="3"/></el-form-item></template>
      </el-form><span slot="footer"><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></span>
    </el-dialog>
  </div>
</template>
<script>
import SupplierDeliveries from '../components/SupplierDeliveries.vue';
import { createFlowItem, deleteFlowItem, fetchFlowItems, fetchOrders, runFlowAction, updateFlowItem, updateFlowStatus } from "../api/client";
const forms={receipts:()=>({order_id:"",material_code:"",material_name:"",received_quantity:1,received_date:null,remark:""}),inspections:()=>({receipt_id:"",inspected_quantity:1,accepted_quantity:1,rejected_quantity:0,rework_quantity:0,defect_description:""}),returns:()=>({receipt_id:"",quantity:1,reason:""})};
export default {components:{SupplierDeliveries},data:()=>({deliveriesVisible:false,active:"receipts",items:[],orders:[],allReceipts:[],loading:false,saving:false,dialogVisible:false,editingId:"",form:forms.receipts(),pagination:{page:1,page_size:10,total:0}}),computed:{activeLabel(){return {receipts:"收货单",inspections:"质量检验",returns:"采购退货"}[this.active];},createButton(){return {receipts:"新建收货单",inspections:"登记质检",returns:"新建退货单"}[this.active];},dialogTitle(){return this.editingId?"编辑收货单":this.createButton;},selectedOrder(){return this.orders.find(item=>item.id===this.form.order_id);},selectedOrderLines(){return this.selectedOrder?this.selectedOrder.lines:[];},inspectableReceipts(){return this.allReceipts.filter(item=>item.status==="received");},returnableReceipts(){return this.allReceipts.filter(item=>item.status==="inspected"&&Number(item.rejected_quantity)>0);}},async created(){await Promise.all([this.load(),this.loadOptions()]);},methods:{statusName(v){return {draft:"草稿",received:"已收货",inspected:"已质检",passed:"合格",partial:"部分合格",failed:"不合格",sent:"已发送",completed:"已完成"}[v]||v;},statusType(v){return {draft:"info",received:"warning",inspected:"success",sent:"warning",completed:"success"}[v]||"";},async load(){this.loading=true;try{const result=await fetchFlowItems(this.active,{page:this.pagination.page,page_size:this.pagination.page_size});this.items=result.items;this.pagination.total=result.total;}catch(_){this.$message.error(`${this.activeLabel}加载失败`);}finally{this.loading=false;}},async loadOptions(){const [orders,receipts]=await Promise.all([fetchOrders({ page: 1, page_size: 100, unfiltered: true }),fetchFlowItems("receipts",{ page: 1, page_size: 100, unfiltered: true })]);this.orders=orders.items;this.allReceipts=receipts.items;},changeTab(){this.pagination.page=1;this.load();this.loadOptions();},changePage(page){this.pagination.page=page;this.load();},changeSize(size){this.pagination.page_size=size;this.pagination.page=1;this.load();},openCreate(){this.editingId="";this.form=forms[this.active]();this.dialogVisible=true;},editReceipt(item){this.editingId=item.id;this.form={...item,received_quantity:Number(item.received_quantity)};this.dialogVisible=true;},selectOrder(){this.form.material_code="";this.form.material_name="";},selectOrderMaterial(code){const line=this.selectedOrderLines.find(item=>item.material_code===code);this.form.material_name=line?line.material_name:"";},selectReceipt(id){const item=this.inspectableReceipts.find(row=>row.id===id);if(item){this.form.inspected_quantity=Number(item.received_quantity)-Number(item.accepted_quantity)-Number(item.rejected_quantity);this.form.accepted_quantity=this.form.inspected_quantity;this.form.rejected_quantity=0;}},selectRejectedReceipt(id){const item=this.returnableReceipts.find(row=>row.id===id);if(item)this.form.quantity=Number(item.rejected_quantity);},async save(){if(this.active==="receipts"&&(!this.form.order_id||!this.form.material_code))return this.$message.warning("请选择采购订单和到货物料");if(this.active==="inspections"&&Number(this.form.accepted_quantity)+Number(this.form.rejected_quantity)!==Number(this.form.inspected_quantity))return this.$message.warning("合格与不合格数量之和必须等于检验数量");if(this.active==="returns"&&(!this.form.receipt_id||!this.form.reason))return this.$message.warning("请选择收货单并填写退货原因");this.saving=true;try{if(this.editingId)await updateFlowItem("receipts",this.editingId,{received_quantity:this.form.received_quantity,received_date:this.form.received_date,remark:this.form.remark});else await createFlowItem(this.active,this.form);this.$message.success(`${this.activeLabel}已保存`);this.dialogVisible=false;await Promise.all([this.load(),this.loadOptions()]);}catch(error){this.$message.error(error.response&&error.response.data&&error.response.data.detail||"保存失败");}finally{this.saving=false;}},async confirmReceipt(item){try{await this.$confirm(`确认收货单 ${item.receipt_no}？确认后进入质检。`,"确认收货",{type:"warning"});await runFlowAction("receipts",item.id,"confirm");this.$message.success("收货已确认");await Promise.all([this.load(),this.loadOptions()]);}catch(error){if(error!=="cancel")this.$message.error("确认失败");}},async advanceReturn(item,status){try{await updateFlowStatus("returns",item.id,status);this.$message.success(status==="sent"?"退货单已发送":"退货已完成");await this.load();}catch(error){this.$message.error("状态更新失败");}},async remove(item){try{await this.$confirm(`确定删除 ${item.receipt_no||item.return_no} 吗？`,"删除确认",{type:"warning"});await deleteFlowItem(this.active,item.id);this.$message.success("已删除");await this.load();}catch(error){if(error!=="cancel")this.$message.error("删除失败");}}}};
</script>
